assignments.value:
* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; background: #f4f3f8; color: #1f1d2b; }
a { color: inherit; }
.topo { background: #fff; border-bottom: 4px solid var(--cor); }
.topo div { max-width: 880px; margin: 0 auto; padding: 12px 16px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.topo img { height: 56px; width: auto; margin: -8px 0; }
.topo b { color: var(--cor); font-size: 1.05rem; }
.topo small { margin-left: auto; color: #6b6880; font-size: .85rem; }
main { max-width: 880px; margin: 20px auto; padding: 0 16px; }
.card { background: #fff; border-radius: 12px; padding: 16px; box-shadow: 0 1px 3px rgba(0,0,0,.08); margin-bottom: 16px; }
.barra { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
h1 { margin: 0 0 4px; font-size: 1.15rem; }
.btn { display: inline-block; padding: 10px 16px; border-radius: 8px; border: 0; background: var(--cor); color: #fff;
       font: 600 .95rem system-ui, sans-serif; text-decoration: none; cursor: pointer; white-space: nowrap; }
.btn.claro { background: #fff; color: var(--cor); border: 1px solid var(--cor); }
.erro { color: #b3261e; background: #fdecea; border-radius: 8px; padding: 12px; margin-bottom: 16px; }
.ok { color: #1d6b3f; background: #e6f4ea; border-radius: 8px; padding: 12px; margin-bottom: 16px;
      display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.muted { color: #6b6880; font-size: .9rem; margin: 0 0 12px; }
